const db = new PrismaClient();

const FAMILY = "plutoniumt4";

const SETUP_SCRIPT = [
  "curl -fsSL https://get.docker.com | sh",
  // Empty bind-mounts only — the customer SFTPs their own legally-owned WaW
  // files into gamefiles/ after deploy. Nothing is downloaded into either
  // directory by this script.
  "mkdir -p /opt/plutoniumt4/gamefiles /opt/plutoniumt4/server",
  [
    "docker run -d --name plutoniumt4 --restart unless-stopped --stop-timeout 30",
    "-p 28960:28960/udp",
    "-e PLUTAINER_GAME='t4mp'",
    "-e PLUTAINER_CONFIG_FILE='dedicated.cfg'",
    "-e PLUTO_SERVER_KEY='changeme-generate-your-own-key-at-plutonium.pw'",
    "-v /opt/plutoniumt4/gamefiles:/home/plutainer/gamefiles",
    "-v /opt/plutoniumt4/server:/home/plutainer/app",
    "ghcr.io/ayymoss/plutainer:latest",
  ].join(" "),
].join(" && ");

async function main() {
  const os = await db.osTemplate.upsert({
    where: { slug: FAMILY },
    create: {
      slug: FAMILY,
      name: "Plutonium T4 (WaW) Server",
      category: "APPLICATION",
      family: FAMILY,
      version: "",
      logo: FAMILY,
      vmid: 9000,
      baseVmid: 9000,
      setupScript: SETUP_SCRIPT,
      minRamMB: 2048,
      minDiskGB: 15,
      licenseRequired: false,
      featured: false,
      sortOrder: 190,
      active: true,
    },
    update: { name: "Plutonium T4 (WaW) Server", setupScript: SETUP_SCRIPT, minRamMB: 2048, minDiskGB: 15, active: true },
  });
  console.log(`  osTemplate ${FAMILY.padEnd(16)} -> ${os.id}`);

  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
  const largest = plans[plans.length - 1];

  // Priced against real competitor data researched for this seed (Legion
  // Hosting's live Plutonium BO1 tiers: $5.02/$11.70/$20.04 regular monthly
  // for 3/7/12 GB) and against Nxeon's own lightweight-community-title tiers
  // already seeded (necesse $4.49, dst $4.99) — T4/WaW's COD4-era engine is
  // light on CPU/RAM even at high slot counts, so pricing sits toward the
  // low end of the catalog rather than scaling with slots the way a modern
  // engine (Rust, ARK) does.
  const TIERS: { name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean }[] = [
    { name: "Plutonium T4 — 2 GB / 18 players", ramMB: 2048, cpuCores: 2, diskGB: 15, slots: 18, priceCents: 599 },
    { name: "Plutonium T4 — 4 GB / 32 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 32, priceCents: 899, featured: true },
    { name: "Plutonium T4 — 6 GB / 64 players", ramMB: 6144, cpuCores: 3, diskGB: 30, slots: 64, priceCents: 1399 },
  ];

  let created = 0;
  let updated = 0;
  let sortOrder = 0;
  for (const t of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= t.ramMB) ?? largest;
    const data = {
      gameFamily: FAMILY,
      name: t.name,
      ramMB: t.ramMB,
      cpuCores: t.cpuCores,
      diskGB: t.diskGB,
      slots: t.slots,
      priceCents: t.priceCents,
      termMonths: 1,
      basePlanId: basePlan.id,
      osTemplateId: os.id,
      featured: t.featured ?? false,
      active: true,
      sortOrder: sortOrder++,
    };
    const existing = await db.gamePlan.findFirst({ where: { gameFamily: FAMILY, name: t.name } });
    if (existing) {
      await db.gamePlan.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await db.gamePlan.create({ data });
      created++;
    }
    console.log(`  plan ${t.name.padEnd(38)} base=${basePlan.name}`);
  }
  console.log(`\nPlutonium T4: 1 OsTemplate, GamePlans ${created} created / ${updated} updated.`);
}

