        family: fam.family,
        version: "",
        logo: fam.family,
        vmid: 9000,
        baseVmid: 9000,
        setupScript: fam.setupScript,
        minRamMB: fam.minRamMB,
        minDiskGB: fam.minDiskGB,
        licenseRequired: false,
        featured: false,
        sortOrder: fam.sortOrder,
        active: true,
      },
      update: { name: fam.osName, setupScript: fam.setupScript, minRamMB: fam.minRamMB, minDiskGB: fam.minDiskGB, active: true },
    });
    console.log(`  osTemplate ${fam.family.padEnd(16)} -> ${os.id}`);

    let sortOrder = 0;
    for (const t of fam.tiers) {
      const basePlan = plans.find((p) => p.ramMB >= t.ramMB) ?? largest;
      const data = {
        gameFamily: fam.family,
        name: t.name,
        ramMB: t.ramMB,
        cpuCores: t.cpuCores,
        diskGB: t.diskGB,
        slots: t.slots,
        priceCents: t.priceCents,
        termMonths: 1,
        basePlanId: basePlan.id,
        osTemplateId: os.id,
        featured: t.featured ?? false,
        active: true,
        sortOrder: sortOrder++,
      };
      const existing = await db.gamePlan.findFirst({ where: { gameFamily: fam.family, name: t.name } });
      if (existing) {
        await db.gamePlan.update({ where: { id: existing.id }, data });
        totalUpdated++;
      } else {
        await db.gamePlan.create({ data });
        totalCreated++;
      }
      console.log(`  plan ${t.name.padEnd(46)} base=${basePlan.name}`);
    }
  }
  console.log(`\nPlutonium (T4/T5/T6/IW5): ${FAMILIES.length} OsTemplates, GamePlans ${totalCreated} created / ${totalUpdated} updated.`);
}

